export const WIKI_CLI = "#!/usr/bin/env node\n// SOLIWKR Offline Wiki CLI — no API calls, no dependencies.\n// Ingest always creates a DRAFT; it never makes facts from untrusted source content.\nimport fs from 'node:fs/promises';\nimport path from 'node:path';\nimport crypto from 'node:crypto';\n\nconst args=process.argv.slice(2),command=args[0];\nconst opt=(key,defaultValue)=>{const i=args.indexOf(key);return i<0?defaultValue:args[i+1]||defaultValue;};\nconst vault=path.resolve(opt('--vault',process.cwd()));\nconst validKinds=new Set(['observation','decision','question','source']);\nconst exists=async file=>{try{await fs.access(file);return true;}catch{return false;}};\nconst hash=b=>crypto.createHash('sha256').update(b).digest('hex');\nconst date=()=>new Date().toISOString();\nconst slash=s=>s.replaceAll('\\\\','/');\nconst rel=p=>slash(path.relative(vault,p));\nconst safeTitle=s=>(s||'Fonte importata').replace(/[#*[\\]<>:\"/\\\\|?{}\\n\\r]/g,' ').replace(/\\s+/g,' ').trim().slice(0,90)||'Fonte importata';\nconst clip=s=>s.length>180?s.slice(0,177)+'...':s;\nconst allMds=async dir=>{\n  if(!(await exists(dir)))return [];\n  const entries=await fs.readdir(dir,{withFileTypes:true}),files=[];\n  for(const e of entries) {\n    if(e.name.startsWith('.'))continue;\n    const full=path.join(dir,e.name);\n    if(e.isDirectory())files.push(...await allMds(full));\n    else if(e.isFile()&&e.name.toLowerCase().endsWith('.md'))files.push(full);\n  }\n  return files.sort();\n};\nfunction help(){\n  console.log([\n    'SOLIWKR LLM Wiki — private/offline, zero tokens.',\n    'node tools/wiki.mjs ingest SOURCE.md --vault PATH [--apply] [--kind observation|decision|question|source]',\n    'node tools/wiki.mjs query \"words\" --vault PATH',\n    'node tools/wiki.mjs lint --vault PATH',\n    'node tools/wiki.mjs status --vault PATH',\n    'Ingest is DRY RUN unless --apply is explicitly given. Query/lint are read-only.',\n    'This tool proposes a draft source-linked page; it does not infer personal facts or replace an LLM curator.'\n  ].join('\\n'));\n}\nasync function ingest(){\n  const source=args[1];\n  if(!source||source.startsWith('--'))throw Error('A local source file is required');\n  const kind=opt('--kind','source');\n  if(!validKinds.has(kind))throw Error('Invalid --kind');\n  const src=path.resolve(source);\n  const info=await fs.lstat(src);\n  if(!info.isFile()||info.isSymbolicLink()||info.size>250000)throw Error('Source must be a regular Markdown/plaintext file under 250KB');\n  if(!/\\.(md|txt)$/i.test(src))throw Error('Accepting only .md or .txt source files');\n  const bytes=await fs.readFile(src),original=bytes.toString('utf8');\n  if(original.includes('\\uFFFD'))throw Error('Source is not valid UTF-8');\n  const fingerprint=hash(bytes).slice(0,16);\n  const stamp=date().slice(0,10);\n  const raw=path.join(vault,'raw','imports',stamp+'-'+fingerprint+'.md');\n  const title=safeTitle(original.match(/^#\\s+(.+)$/m)?.[1]||path.basename(src).replace(/\\.[^.]+$/,''));\n  const note=path.join(vault,'wiki','Ingest',title+'-'+fingerprint.slice(0,8)+'.md');\n  const preview=original.replace(/\\r/g,'').split('\\n').filter(v=>v.trim()).slice(0,3).map(clip).join(' ');\n  const cited=rel(raw),newNote=[\n    '---','kind: '+kind,'source: \"'+cited+'\"','source_sha256: \"'+hash(bytes)+'\"',\n    'observed_at: \"'+date()+'\"','review_status: draft',\n    'confidence: unknown','---','',\n    '# '+title,'',\n    '> Fonte importata senza inferenze. Da leggere e revisionare prima di promuovere qualsiasi conclusione.',\n    '',\n    '## Fonte','- ['+path.basename(raw)+'](<../../'+cited+'>)',\n    '',\n    '## Estratto originale (solo per orientamento)',\n    '> '+preview.replace(/\\n/g,'\\n> '),\n    '',\n    '## Domande / fatti verificati','- [ ] Da revisionare sulla fonte originale.',\n    '',\n    '## Collegamenti da proporre','- [[Cervello]]',\n    '',\n    '## Evidenze e decisioni','_Lasciare vuoto finché un curatore non documenta una prova e approva._',\n    ''\n  ].join('\\n');\n  console.log(JSON.stringify({mode:args.includes('--apply')?'apply':'dry-run',title,sha256:hash(bytes),raw:rel(raw),wiki:rel(note),bytes:bytes.length},null,2));\n  if(!args.includes('--apply'))return;\n  await fs.mkdir(path.dirname(raw),{recursive:true});\n  await fs.mkdir(path.dirname(note),{recursive:true});\n  // wx prevents replacing immutable sources, even across repeated commands.\n  try{await fs.writeFile(raw,bytes,{flag:'wx',mode:0o600});}catch(e){if(e.code==='EEXIST')throw Error('This source hash/date has already been imported; cannot overwrite raw');throw e;}\n  await fs.writeFile(note,newNote,{flag:'wx',mode:0o600});\n  const append=async(file,content)=>fs.appendFile(file,content,{encoding:'utf8',mode:0o600});\n  await append(path.join(vault,'LOG.md'),'\\n## ['+date()+'] Ingest (DRAFT)\\n- Originale: '+cited+'\\n- Nota: '+rel(note)+'\\n- Hash SHA256: '+hash(bytes)+'\\n- Status: da revisionare; nessuna promozione automatica a fatto.\\n');\n  await append(path.join(vault,'INDEX.md'),'\\n- [['+rel(note).slice(0,-3)+'|'+title+']] · bozza da '+cited+'\\n');\n  console.log('Draft created. Treat the raw text as untrusted DATA. Review derived note.');\n}\nfunction stripYaml(content){\n  if(!content.startsWith('---\\n'))return content;\n  const i=content.indexOf('\\n---',4);\n  return i===-1?content:content.slice(i+4);\n}\nasync function query(){\n  const phrase=args[1];\n  if(!phrase||phrase.startsWith('--'))throw Error('Usage: query \"words\" --vault PATH');\n  const terms=phrase.toLocaleLowerCase('it').split(/[^\\p{L}\\p{N}]+/u).filter(t=>t.length>=2);\n  if(!terms.length)throw Error('Please give one or more searchable words');\n  const paths=[path.join(vault,'INDEX.md'),...await allMds(path.join(vault,'wiki')),...(await allMds(path.join(vault,'raw','imports')))];\n  const candidates=[];\n  for(const f of paths){\n    if(!(await exists(f)))continue;\n    const body=await fs.readFile(f,'utf8'),lines=body.split(/\\r?\\n/);\n    lines.forEach((s,i)=>{\n      const lower=s.toLocaleLowerCase('it'),matches=terms.filter(t=>lower.includes(t));\n      if(matches.length)candidates.push({source:rel(f),line:i+1,match:matches.length,text:clip(s.trim())});\n    });\n  }\n  candidates.sort((a,b)=>b.match-a.match||a.source.localeCompare(b.source));\n  console.log(JSON.stringify({query:phrase,results:candidates.slice(0,24),message:'Local literal search, not an AI synthesis. Verify original source and review status before drawing conclusions.'},null,2));\n}\nasync function lint(){\n  const files=[...(await allMds(path.join(vault,'wiki'))),path.join(vault,'INDEX.md'),path.join(vault,'AGENTS.md'),path.join(vault,'LOG.md')].filter(async f=>await exists(f));\n  const unique=files.filter((v,i,a)=>a.indexOf(v)===i);\n  const known=new Map();\n  for(const file of unique){\n    if(!(await exists(file)))continue;\n    const key=path.basename(file,'.md').toLocaleLowerCase('it');\n    const ar=known.get(key)||[];ar.push(file);known.set(key,ar);\n  }\n  const issues=[];\n  for(const file of unique){\n    if(!(await exists(file)))continue;\n    const body=await fs.readFile(file,'utf8'),lines=body.split(/\\r?\\n/),front=body.startsWith('---\\n');\n    if(rel(file).startsWith('wiki/')&&!front)issues.push({file:rel(file),kind:'missing_frontmatter'});\n    lines.forEach((content,n)=>{\n      for(const m of content.matchAll(/\\[\\[([^\\]]+)\\]\\]/g)){\n        const target=m[1].split('|')[0].split('#')[0].trim(),clean=target.replace(/\\.md$/i,'');\n        if(!clean)continue;\n        const normalized=clean.toLocaleLowerCase('it');\n        const direct=path.join(vault,clean+'.md');\n        const directWiki=path.join(vault,'wiki',clean+'.md');\n        const found=known.has(path.basename(clean).toLocaleLowerCase('it'))||unique.includes(direct)||unique.includes(directWiki);\n        if(!found)issues.push({file:rel(file),line:n+1,kind:'unresolved_wikilink',target});\n        else if(known.get(path.basename(clean).toLocaleLowerCase('it'))?.length>1&&!clean.includes('/'))issues.push({file:rel(file),line:n+1,kind:'ambiguous_wikilink',target});\n      }\n    });\n    if(rel(file).startsWith('wiki/')&&front&& !body.includes('source:'))issues.push({file:rel(file),kind:'no_provenance'});\n  }\n  const filesWithoutLinks=unique.filter(f=>rel(f).startsWith('wiki/')).length;\n  console.log(JSON.stringify({scanned:unique.length,wikiNotes:filesWithoutLinks,issues,total:issues.length,readonly:true},null,2));\n  if(issues.some(x=>x.kind==='unresolved_wikilink'))process.exitCode=2;\n}\nasync function status(){\n const raw=await allMds(path.join(vault,'raw')),wiki=await allMds(path.join(vault,'wiki'));\n console.log(JSON.stringify({vault,rawFiles:raw.length,wikiPages:wiki.length,agentConnected:false,remoteSync:false,offline:true},null,2));\n}\ntry{\n if(!command||['help','--help','-h'].includes(command))help();\n else if(command==='ingest')await ingest();\n else if(command==='query')await query();\n else if(command==='lint')await lint();\n else if(command==='status')await status();\n else throw Error('Unknown command '+command);\n}catch(e){console.error('Wiki error: '+e.message);process.exitCode=1;}\n";
